cat > UITapTests/TapTests.swift <<'EOF'
import XCTest
final class TapTests: XCTestCase {
    override func setUpWithError() throws { continueAfterFailure = false }
    func testTap() {
        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        let open = springboard.alerts.buttons["Open"]
        if open.waitForExistence(timeout: 4) { open.tap() }
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()
        sleep(2)
        app.coordinate(withNormalizedOffset: CGVector(dx: 0.087, dy: 0.088)).tap()
        sleep(2)
        print("AFTER_PROFILE_TAP\n\(app.debugDescription)")
    }
}
EOF
