import XCTest
final class TapTests: XCTestCase {
 override func setUpWithError() throws { continueAfterFailure = false }
 func testTap() {
  let app = XCUIApplication(bundleIdentifier: "im.vector.app")
  app.activate()
  let userSettings = app.buttons["User settings"]
  if !userSettings.waitForExistence(timeout: 3) {
   app.coordinate(withNormalizedOffset: CGVector(dx: 0.087, dy: 0.088)).tap()
  }
  XCTAssertTrue(userSettings.waitForExistence(timeout: 5))
  userSettings.tap()
  sleep(2)
  print("SETTINGS_SCREEN\n\(app.debugDescription)")
 }
}
