  if !userSettings.waitForExistence(timeout: 3) {
   app.coordinate(withNormalizedOffset: CGVector(dx: 0.087, dy: 0.088)).tap()
  }
  XCTAssertTrue(userSettings.waitForExistence(timeout: 5))
  userSettings.tap()
  sleep(2)
  print("SETTINGS_SCREEN\n\(app.debugDescription)")
 }
